INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einer Betriebsvereinbarung?', 2, '[{"text": "Vereinbarung zwischen Betriebsrat und Arbeitgeber", "correct": true, "because": "Regelt Arbeitsbedingungen"}, {"text": "Vertrag mit Kunden", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Betriebsvereinbarung?', 3, '[{"text": "Regelung von Arbeitsbedingungen", "correct": true, "because": "Klarheit für Mitarbeiter"}, {"text": "Systemleistung steigern", "correct": false, "because": "Kein technisches Ziel"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Themen können in einer Betriebsvereinbarung geregelt werden?', 5, '[{"text": "Arbeitszeiten", "correct": true, "because": "Regelung möglich"}, {"text": "Nutzung von IT-Systemen", "correct": true, "because": "IT-Betrieb betroffen"}, {"text": "Marketingstrategien", "correct": false, "because": "Kein Betriebsbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Betriebsvereinbarung ist freiwillig. b) Sie ist gesetzlich vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Freiwillig, aber bindend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Betriebsvereinbarung?', 4, '[{"text": "Betriebsrat", "correct": false, "because": "Mitgestalter"}, {"text": "Arbeitsbedingungen", "correct": false, "because": "Kern der Vereinbarung"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Betriebsvereinbarung den Betriebsrat erfordert?', 2, '[{"text": "Ja", "correct": true, "because": "Partner des Arbeitgebers"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz bildet die Grundlage für Betriebsvereinbarungen?', 3, '[{"text": "Betriebsverfassungsgesetz", "correct": true, "because": "§ 77 BetrVG"}, {"text": "Arbeitszeitgesetz", "correct": false, "because": "Anderer Bereich"}, {"text": "Mindestlohngesetz", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Erstellung einer Betriebsvereinbarung?', 5, '[{"text": "Verhandlungen mit Betriebsrat", "correct": true, "because": "Zusammenarbeit nötig"}, {"text": "Schriftform", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Marketingplan", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Betriebsvereinbarungen regeln Arbeitszeiten. b) Sie sind nur für große Firmen nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Betriebe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Betriebsvereinbarung unwichtig?', 4, '[{"text": "Verbindlichkeit", "correct": false, "because": "Rechtsverbindlich"}, {"text": "Beteiligung des Betriebsrats", "correct": false, "because": "Pflicht"}, {"text": "Farbe des Papiers", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss eine Betriebsvereinbarung schriftlich sein?', 2, '[{"text": "Ja", "correct": true, "because": "§ 77 BetrVG"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Betriebsvereinbarung für Fachinformatiker?', 4, '[{"text": "Klare Arbeitsregeln", "correct": true, "because": "Transparenz"}, {"text": "Bessere Arbeitsbedingungen", "correct": true, "because": "Mitbestimmung"}, {"text": "Schnellere Systeme", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Betriebsvereinbarungen nur Arbeitszeiten betreffen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IT-Nutzung, Datenschutz"}, {"text": "Ja", "correct": false, "because": "Breiter anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Betriebsvereinbarung?', 3, '[{"text": "Einvernehmen mit Betriebsrat", "correct": true, "because": "Zusammenarbeit"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Betriebsvereinbarungen können IT-Nutzung regeln. b) Sie sind gesetzlich bindend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bindend nur intern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine fehlende Betriebsvereinbarung?', 5, '[{"text": "Unklare Regeln", "correct": true, "because": "Keine Klarheit"}, {"text": "Konflikte mit Mitarbeitern", "correct": true, "because": "Keine Einigung"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei einer Betriebsvereinbarung?', 3, '[{"text": "Technische Umsetzung unterstützen", "correct": true, "because": "z.B. IT-Regeln"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Betriebsvereinbarung IT-spezifisch sein?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. Datenschutz"}, {"text": "Nein", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Thema könnte eine Betriebsvereinbarung regeln?', 4, '[{"text": "Nutzung von Betriebssoftware", "correct": true, "because": "IT-Betrieb"}, {"text": "Produktwerbung", "correct": false, "because": "Kein Betriebsbezug"}, {"text": "Büroverschönerung", "correct": false, "because": "Irrelevant"}]');
